export function LocalisationL10n({
  region = "{{region}}",
  showUnits = {{showUnits}},
  accent = "{{accent}}",
  productName = "{{productName}}",
}) {
  const data = {
    us: { price: "$64.00", date: "Ships 3/14/2026", unit: "Capacity: 1.5 gal \u00B7 22 in tall" },
    uk: { price: "\u00A351.00", date: "Ships 14/03/2026", unit: "Capacity: 6.8 L \u00B7 56 cm tall" },
    jp: { price: "\u00A59,600", date: "Ships 2026\u5E743\u670814\u65E5", unit: "Capacity: 6.8 L \u00B7 56 cm tall" },
  }[region];
  return (
    <div style={{ font: "13px/1.6 system-ui, sans-serif", color: "#241430", background: "#FAF7F2", padding: 18, borderRadius: 12, width: 280, boxSizing: "border-box" }}>
      <p style={{ margin: "0 0 8px", fontWeight: 700 }}>{productName}</p>
      <p style={{ margin: "0 0 4px", fontSize: 22, fontWeight: 800, color: accent }}>{data.price}</p>
      <p style={{ margin: "0 0 4px", fontSize: 11, color: "#24143099" }}>{data.date}</p>
      {showUnits && <p style={{ margin: "0 0 4px", fontSize: 11, color: "#24143099" }}>{data.unit}</p>}
    </div>
  );
}
